'use strict';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={legal_name:'Legal name',legal_form:'Legal form',industry:'Registered industry',registered_address:'Registered address',employees:'Registered employees',bankrupt:'Bankruptcy flag',liquidating:'Liquidation flag',registry_website_candidate:'Website candidate',latest_filing_year:'Latest filing year',registered_roles:'Registered roles',registered_workplaces:'Registered workplaces','financial.revenue':'Revenue','financial.operating_result':'Operating result','financial.annual_result':'Annual result','financial.assets':'Assets','financial.equity':'Equity','financial.debt':'Debt'};
let rows=[],selected=null,tab='overview',report=null,imported=false;
const fact=(r,field)=>r.claims.find(c=>c.field===field);
const available=c=>c?.availability==='available';
const initial=r=>(r.legal_identity?.name||r.organisation_number).split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const name=r=>r.legal_identity?.name||'Unresolved company';
const city=r=>fact(r,'registered_address')?.value?.poststed||'Address unavailable';
const number=v=>new Intl.NumberFormat('en-GB',{notation:'compact',maximumFractionDigits:2}).format(v);
const fullNumber=v=>new Intl.NumberFormat('en-GB',{maximumFractionDigits:2}).format(v);
const date=v=>v?new Date(v).toLocaleString('en-GB',{dateStyle:'medium',timeStyle:'short',timeZone:'UTC'})+' UTC':'Not recorded';
const period=c=>c?.reporting_period?.tilDato?.slice(0,4)||'';
function display(c){if(!c||!available(c))return 'Not available';const v=c.value;if(v&&typeof v==='object'){if('amount'in v)return `${fullNumber(v.amount)} ${v.currency||'currency not stated'}`;if(Array.isArray(v))return `${v.length} ${c.field==='registered_roles'?(v.length===1?'role':'roles'):(v.length===1?'workplace':'workplaces')}`;if(c.field==='industry')return `${v.kode||''} · ${v.beskrivelse||''}`;if(c.field==='registered_address')return [...(v.adresse||[]),[v.postnummer,v.poststed].filter(Boolean).join(' '),v.land].filter(Boolean).join(', ');return JSON.stringify(v);}if(typeof v==='boolean')return v?'Yes':'No';return String(v);}
function summaryValue(c){if(!available(c))return 'Not available';return c.value&&typeof c.value==='object'&&'amount'in c.value?`${number(c.value.amount)} <small style="font-size:10px;font-weight:400;letter-spacing:0">${esc(c.value.currency||'')}</small>`:esc(display(c));}
function safeURL(v){try{const u=new URL(v);return u.protocol==='https:'||u.protocol==='http:'?u.href:null;}catch{return null;}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function download(value,filename){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function openDialog(html){$('#dialog-content').innerHTML=html;if(!$('#inspector').open)$('#inspector').showModal();}
$('#close-dialog').onclick=()=>$('#inspector').close();
$('#inspector').addEventListener('click',e=>{if(e.target===$('#inspector')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
function renderList(){const q=$('#search').value.toLocaleLowerCase().trim(),filter=$('#filter').value;const list=rows.filter(r=>[name(r),r.organisation_number,city(r)].join(' ').toLocaleLowerCase().includes(q)&&(filter!=='website'||available(fact(r,'registry_website_candidate')))&&(filter!=='gaps'||r.claims.some(c=>!available(c))||r.errors.length));$('#result-count').textContent=`${list.length} ${list.length===1?'company':'companies'}`;$('#companies').innerHTML=list.length?list.map(r=>`<button class="company ${selected===r?'selected':''}" data-org="${esc(r.organisation_number)}" aria-pressed="${selected===r}"><span class="avatar" aria-hidden="true">${esc(initial(r))}</span><span class="company-text"><strong>${esc(name(r))}</strong><small>${esc(city(r))} · ${esc(r.organisation_number)}</small></span>${selected===r?'<span class="company-arrow" aria-hidden="true">›</span>':''}</button>`).join(''):'<p class="no-results">No matching companies.<br>Try a name, city or organisation number.</p>';$('#companies').querySelectorAll('[data-org]').forEach(b=>b.onclick=()=>{selected=rows.find(r=>r.organisation_number===b.dataset.org);tab='overview';renderList();renderProfile();});}
function metric(c,title,foot){const index=selected.claims.indexOf(c);return `<button class="metric" data-claim="${index}" aria-label="Inspect ${esc(title)} evidence"><span class="metric-label">${esc(title)}</span><span class="metric-value ${available(c)?'':'missing'}">${summaryValue(c)}</span><span class="metric-foot">${esc(foot)}</span><span class="metric-arrow" aria-hidden="true">↗</span></button>`;}
function factRow(field,label){const c=fact(selected,field);return `<button class="fact-row" data-claim="${selected.claims.indexOf(c)}"><span class="fact-label">${esc(label)}</span><span class="fact-value">${esc(display(c))} <span class="muted">↗</span></span></button>`;}
function overview(){const r=selected,revenue=r.claims.filter(c=>c.field==='financial.revenue'),latest=revenue[0],employees=fact(r,'employees'),roles=fact(r,'registered_roles');const years=[...revenue].filter(available).reverse().slice(-4);const max=Math.max(1,...years.map(c=>Math.abs(c.value.amount)));return `<div class="section-line"><h3>A clearer first look</h3><span>Click a fact to inspect its evidence ↗</span></div><div class="metrics">${metric(latest,'Revenue',latest?`Filed period ending ${latest.reporting_period.tilDato}`:'No matching legal-company statement')}${metric(employees,'Registered employees','Registry value · not a live headcount')}${metric(roles,'Public business roles','Active roles · personal birth dates removed')}</div><div class="insight"><span class="insight-icon" aria-hidden="true">✳</span><div><strong>A legal-company view, with the gaps left visible.</strong><p>${esc(r.synthesis?.text||'Official identity and accounts only. External operating activity is unverified.')} Group accounts are excluded. Website candidates remain unverified.</p></div></div><div class="detail-grid"><section class="detail-block"><h3>Registered identity</h3>${factRow('legal_form','Legal form')}${factRow('latest_filing_year','Latest filing')}${factRow('bankrupt','Bankruptcy flag')}${factRow('liquidating','Liquidation flag')}${factRow('registered_workplaces','Workplaces')}<p class="mini-label">These are registry observations, not a recommendation or credit assessment.</p></section><section class="detail-block"><h3>Revenue through the filings <span class="muted">· ${esc(latest?.value?.currency||'')}</span></h3>${years.length?`<div class="revenue-bars" role="img" aria-label="Filed revenue: ${esc(years.map(c=>period(c)+': '+display(c)).join('; '))}">${years.map(c=>`<button class="bar-group" data-claim="${r.claims.indexOf(c)}" aria-label="Inspect ${esc(period(c))} revenue"><span class="bar-number">${esc(number(c.value.amount))}</span><span class="bar-fill ${c.value.amount<0?'negative-bar':''}" style="height:${Math.max(2,Math.abs(c.value.amount)/max*80)}px"></span><span class="bar-year">${esc(period(c))}</span></button>`).join('')}</div>`:'<div class="empty"><p>No available revenue evidence in this snapshot.</p></div>'}<p class="mini-label">Filed company statements only. Bar height shows magnitude; negative values are brown. Different reporting periods may not be comparable.</p></section></div>`;}
function evidencePanel(){return `<div class="section-line"><h3>Every claim, inspectable</h3><span>${selected.claims.length} observations</span></div><div class="table-wrap"><table class="evidence-table"><thead><tr><th>FIELD / PERIOD</th><th>PUBLISHED VALUE</th><th>AVAILABILITY</th><th>EVIDENCE</th></tr></thead><tbody>${selected.claims.map((c,i)=>`<tr><td>${esc(labels[c.field]||c.field)}${period(c)?`<br><span class="muted">${esc(c.reporting_period.fraDato)} → ${esc(c.reporting_period.tilDato)}</span>`:''}</td><td>${esc(display(c))}</td><td><span class="status ${available(c)?'':'gap'}">${esc(c.availability.replaceAll('_',' '))}</span></td><td><button data-claim="${i}">${c.evidence_ids.length?'Inspect ↗':'View reason ↗'}</button></td></tr>`).join('')}</tbody></table></div>`;}
function changesPanel(){const a=selected.changes;return a.length?`<div class="section-line"><h3>What changed between observations</h3><span>${a.length} recorded differences</span></div>${a.map((c,i)=>`<article class="timeline-item"><h3>${esc(labels[c.after?.field||c.before?.field]||'Observation')} · ${esc(c.kind.replaceAll('_',' '))}</h3><p>Before: ${esc(display(c.before))}<br>After: ${esc(display(c.after))}</p><button data-change="${i}">Compare the evidence ↗</button></article>`).join('')}`:`<div class="empty"><div class="empty-icon" aria-hidden="true">↻</div><h3>${selected.run.previous_run_id?'No recorded material changes.':'A first observation, not a change history.'}</h3><p>${selected.run.previous_run_id?'Values and availability matched the previous run. Retrieval times alone do not create changes.':'Run the agent again with --previous to compare against this snapshot. Prior sources stay attached; changed values and unavailable observations are reported separately.'}</p></div>`;}
function gapsPanel(){const candidate=fact(selected,'registry_website_candidate');return `<div class="section-line"><h3>What we can’t establish yet</h3><span>Abstention is not coverage</span></div><article class="gap-card"><span class="status gap">${available(candidate)?'unverified candidate':'not discovered'}</span><strong>Official operating website</strong><p>${available(candidate)?`The registry lists ${esc(candidate.value)}. This is a discovery candidate, not proof of the operating brand or its exact legal entity.`:'The registry did not supply a website candidate. No domain has been inferred from the company name.'}</p></article><article class="gap-card"><span class="status gap">not collected</span><strong>Jobs, news, social activity and independent sentiment</strong><p>The current agent uses official registries only. It does not scrape restricted platforms or present company promotion as independent sentiment. These fields have no measured external recall.</p></article>${selected.claims.filter(c=>!available(c)).map(c=>`<article class="gap-card"><span class="status gap">${esc(c.availability.replaceAll('_',' '))}</span><strong>${esc(labels[c.field]||c.field)} ${esc(period(c))}</strong><p>${esc(c.reason||'The selected source does not publish this field in the retrieved record. No value has been imputed.')}</p></article>`).join('')}${selected.errors.map(e=>`<article class="gap-card"><strong>${esc(e.module||'Collector')} · ${esc(e.kind)}</strong><p>${esc(e.message)}</p></article>`).join('')}`;}
function renderProfile(){if(!selected)return;const r=selected;const currentSources=new Set(r.claims.flatMap(c=>c.evidence_ids));$('#profile').innerHTML=`<div class="profile-card"><div class="profile-top"><div class="profile-heading"><div class="profile-avatar" aria-hidden="true">${esc(initial(r))}</div><div class="profile-title"><h2>${esc(name(r))}</h2><div class="profile-id"><span>NO ${esc(r.organisation_number)}</span><span>${esc(city(r))}</span><span class="identity-pill">${r.legal_identity?'✓ Exact registry identity':'Identity unresolved'}</span></div></div><button class="export" id="export">Export profile ↓</button></div><p class="profile-sub"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 21V7l8-4 8 4v14M9 21v-5h6v5M8 9h2m4 0h2M8 12h2m4 0h2"/></svg>${esc(display(fact(r,'industry')))}</p><div class="tabs" role="tablist" aria-label="Profile sections">${[['overview','Overview'],['evidence','Evidence'],['changes','Changes'],['gaps','Gaps & limits']].map(([id,label])=>`<button class="tab" role="tab" id="tab-${id}" aria-controls="tabpanel" aria-selected="${tab===id}" tabindex="${tab===id?0:-1}" data-tab="${id}">${label}${id==='evidence'?` <span>${r.claims.length}</span>`:''}</button>`).join('')}</div></div><div class="panel" id="tabpanel" role="tabpanel" aria-labelledby="tab-${tab}">${({overview,evidence:evidencePanel,changes:changesPanel,gaps:gapsPanel})[tab]()}</div><div class="source-footer"><span><span class="live-dot" style="display:inline-block;margin-right:6px"></span>${currentSources.size} current sources · Collected ${esc(date(r.run.completed_at))}</span><button id="run-details">Inspect run details ↗</button></div></div>`;$('#export').onclick=()=>download(r,`fjord-${r.organisation_number}.json`);$('#run-details').onclick=()=>runDetails();document.querySelectorAll('[data-tab]').forEach(b=>{b.onclick=()=>{tab=b.dataset.tab;renderProfile();$(`#tab-${tab}`).focus({preventScroll:true});};b.onkeydown=e=>{const ids=['overview','evidence','changes','gaps'];let i=ids.indexOf(tab);if(['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();tab=ids[e.key==='Home'?0:e.key==='End'?3:(i+(e.key==='ArrowRight'?1:3))%4];renderProfile();$(`#tab-${tab}`).focus({preventScroll:true});}};});document.querySelectorAll('[data-claim]').forEach(b=>b.onclick=()=>inspectClaim(Number(b.dataset.claim)));document.querySelectorAll('[data-change]').forEach(b=>b.onclick=()=>inspectChange(Number(b.dataset.change)));}
function sourceHTML(source){if(!source)return '<p class="dialog-lead">No retrieved source supports this observation. Its failure reason is explicit.</p>';const url=safeURL(source.source_url);return `<dl class="source-meta"><div><dt>Source</dt><dd>${url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(source.source_url)} ↗</a>`:esc(source.source_url)}</dd></div><div><dt>Retrieved</dt><dd>${esc(date(source.retrieved_at))}</dd></div><div><dt>Source classification</dt><dd>${esc(source.source_class)}</dd></div><div><dt>Raw content SHA-256</dt><dd>${esc(source.content_sha256)}</dd></div><div><dt>Saved snapshot SHA-256</dt><dd>${esc(source.snapshot_sha256)}</dd></div>${source.snapshot_projection?`<div><dt>Privacy projection</dt><dd>${esc(source.snapshot_projection)}</dd></div>`:''}</dl><details><summary>Inspect saved source snapshot</summary><pre>${esc(JSON.stringify(source.snapshot,null,2))}</pre></details>`;}
function inspectClaim(index){const c=selected.claims[index];if(!c){openDialog('<h2 class="dialog-title" id="dialog-title">No source observation</h2><p class="dialog-lead">This field was not collected. No value has been inferred.</p>');return;}const source=selected.evidence.find(s=>s.id===c.evidence_ids[0]);openDialog(`<h2 class="dialog-title" id="dialog-title">${esc(labels[c.field]||c.field)}</h2><p class="dialog-lead">${esc(display(c))}</p><span class="status ${available(c)?'':'gap'}">${esc(c.availability.replaceAll('_',' '))}</span>${c.reason?`<p class="dialog-lead" style="margin-top:14px">${esc(c.reason)}</p>`:''}<dl class="source-meta"><div><dt>Extraction method / location</dt><dd>Deterministic JSON field extraction · ${esc(c.extraction_path||'No extraction')}</dd></div>${c.reporting_period?`<div><dt>Reporting period</dt><dd>${esc(c.reporting_period.fraDato)} → ${esc(c.reporting_period.tilDato)}</dd></div>`:''}</dl>${sourceHTML(source)}`);}
function inspectChange(index){const c=selected.changes[index];const old=selected.evidence.find(s=>s.id===c.before?.evidence_ids?.[0]),fresh=selected.evidence.find(s=>s.id===c.after?.evidence_ids?.[0]);openDialog(`<h2 class="dialog-title" id="dialog-title">Compare the observations</h2><p class="dialog-lead">${esc(c.kind.replaceAll('_',' '))} · ${esc(labels[c.after?.field||c.before?.field]||'Field')}</p><h3>Before · ${esc(display(c.before))}</h3>${sourceHTML(old)}<hr style="border:0;border-top:1px solid var(--line);margin:25px 0"><h3>After · ${esc(display(c.after))}</h3>${sourceHTML(fresh)}`);}
function runDetails(){openDialog(`<h2 class="dialog-title" id="dialog-title">An honest run record.</h2><p class="dialog-lead">This interface displays collected snapshots. It does not run a crawler in your browser. Use the Python agent to collect a fresh batch, then import the output here.</p><pre>${esc(JSON.stringify({company_run:selected.run,operations:selected.operations,batch_report:report},null,2))}</pre><p class="dialog-lead">Completion measures whether results were emitted. Exact-company precision, external recall and official qualification have not been independently evaluated.</p>`);}
function help(){openDialog(`<h2 class="dialog-title" id="dialog-title">Your batch. Same paper trail.</h2><p class="dialog-lead">Clone the public repository and use Python 3.11 or later. The collector uses the standard library: no API key, model or paid service required. Each nonblank input line is an organisation number in JSON or an object with organisation_number.</p><pre>python agent.py --input data/smoke-input.jsonl --output out/run.jsonl --max-requests 500 --seconds 600</pre><p class="dialog-lead">Refresh while retaining prior evidence:</p><pre>python agent.py --input data/smoke-input.jsonl --output out/refresh.jsonl --previous out/run.jsonl</pre><p class="dialog-lead">Import run.jsonl using “Import a run”. Files are read locally in your browser, up to 10 MB; nothing is uploaded. Official evaluation uses the organizer's supplied batch and budget.</p><a class="dialog-button" href="https://github.com/nqtexd/fjord-signalpost" target="_blank" rel="noopener noreferrer" style="display:inline-block;text-decoration:none">Open source & run instructions ↗</a>`);}
$('#run-help').onclick=help;
$('#about').onclick=()=>openDialog(`<h2 class="dialog-title" id="dialog-title">Useful evidence. Visible limits.</h2><p class="dialog-lead">Fjord is a research prototype for Signalpost. The sample comes from the organizer's public Norwegian company universe, selected with a fixed random seed. Identity, accounts, roles and workplaces come from Brønnøysundregistrene public APIs under the Norwegian Licence for Open Government Data (NLOD 2.0).</p><p class="dialog-lead">The agent does not infer finances, merge parent and subsidiary records, verify operating websites or collect social/news/jobs activity. Role snapshots discard birth dates and personal identifiers. Public data may still be incomplete or outdated. No official score or qualification is claimed.</p><p class="dialog-lead">AI assistance was used in research, design, code and testing. The evidence values are retrieved registry observations, not generated company facts.</p>`);
$('#search').oninput=renderList;$('#filter').onchange=renderList;
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#inspector').open){e.preventDefault();$('#search').focus();}});
$('#import').onclick=()=>$('#file').click();
function validateRecords(data){if(!Array.isArray(data)||!data.length||data.length>1500)throw Error('Use between 1 and 1,500 company envelopes.');const ids=new Set();for(const r of data){if(!r||!/^\d{9}$/.test(r.organisation_number)||ids.has(r.organisation_number)||!Array.isArray(r.claims)||!Array.isArray(r.evidence)||!Array.isArray(r.errors)||!Array.isArray(r.changes)||!r.run||r.claims.length>500||r.evidence.length>200)throw Error('Invalid, duplicate or oversized company envelope.');for(const c of r.claims){if(typeof c.field!=='string'||!Array.isArray(c.evidence_ids)||!['available','not_available','blocked','not_applicable','ambiguous','failed'].includes(c.availability))throw Error('Invalid claim schema.');}ids.add(r.organisation_number);}return data;}
$('#file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>10_000_000)throw Error('The local import limit is 10 MB.');const text=await file.text();let data;try{const d=JSON.parse(text);data=Array.isArray(d)?d:d.companies||[d];}catch{data=text.split(/\r?\n/).filter(x=>x.trim()).map(x=>JSON.parse(x));}rows=validateRecords(data);selected=rows[0];report=null;imported=true;tab='overview';$('#search').value='';$('#filter').value='all';setDatasetLabels();renderList();renderProfile();toast(`Imported ${rows.length} company records locally.`);}catch(err){toast('Import failed: '+err.message);}finally{e.target.value='';}};
function setDatasetLabels(){$('#library-count').textContent=rows.length;$('#snapshot-note').textContent=imported?`${rows.length} locally imported company snapshots · no upload`: `${rows.length} measured company snapshots · read-only sample, not a live crawl`;$('#collected').textContent=imported?'Local file · not independently verified':`Collected ${new Date(rows[0].run.completed_at).toLocaleDateString('en-GB',{dateStyle:'medium',timeZone:'UTC'})}`;}
async function start(){try{const response=await fetch('sample.json');if(!response.ok)throw Error('Dataset unavailable');const data=await response.json();rows=validateRecords(data.companies);report=data.report;selected=rows.find(r=>r.organisation_number==='879899222')||rows[0];setDatasetLabels();renderList();renderProfile();}catch(err){$('#profile').innerHTML=`<div class="empty"><h3>Could not load the snapshot.</h3><p>${esc(err.message)}. Serve this folder over HTTP, or import a collected JSONL run.</p></div>`;$('#result-count').textContent='No data loaded';}}
start();
